650	    /**
651	     * Tutti i media asset del record (ogni cartella), caricati una sola volta
652	     * per request. Base delle opzioni dei filtri e della vista piatta filtrata.
653	     *
654	     * @return EloquentCollection<int, Media>
655	     */
656	    private function recordAssets(): EloquentCollection
657	    {
658	        if ($this->recordAssetsCache !== null) {
659	            return $this->recordAssetsCache;
660	        }
661	
662	        $owner = $this->resolveOwner();
663	
664	        /** @var EloquentCollection<int, Media> $media */
665	        $media = $owner->media()
666	            ->where('collection_name', $owner->assetsCollection())
667	            ->orderBy('order_column')
668	            ->get();
669	
670	        return $this->recordAssetsCache = $media;
671	    }
