673	    /**
674	     * Media del record che superano i filtri attivi (tipo, autore, intervallo
675	     * di caricamento). Filtro in PHP sulla collezione già caricata: gli asset
676	     * di un singolo record sono in numero contenuto, e il "tipo" (categoria
677	     * mime/estensione) non è una colonna interrogabile in SQL.
678	     *
679	     * @return \Illuminate\Support\Collection<int, Media>
680	     */
681	    private function filteredAssets(): \Illuminate\Support\Collection
682	    {
683	        $type = AssetFileType::tryFromName($this->filterType);
684	        $uploadedBy = is_numeric($this->filterUploadedBy) ? (int) $this->filterUploadedBy : null;
685	        $from = $this->isFilled($this->filterUploadedFrom) ? (string) $this->filterUploadedFrom : null;
686	        $to = $this->isFilled($this->filterUploadedTo) ? (string) $this->filterUploadedTo : null;
687	        // estremi dell'intervallo peso in byte, solo quelli che restringono davvero
688	        $activeMin = $this->activeMinSizeMb();
689	        $activeMax = $this->activeMaxSizeMb();
690	        $minBytes = $activeMin !== null ? (int) ($activeMin * 1024 * 1024) : null;
691	        $maxBytes = $activeMax !== null ? (int) ($activeMax * 1024 * 1024) : null;
692	
693	        return $this->recordAssets()
694	            ->filter(function (Media $media) use ($type, $uploadedBy, $from, $to, $minBytes, $maxBytes): bool {
695	                if ($type !== null && AssetFileType::fromMedia($media) !== $type) {
696	                    return false;
697	                }
698	
699	                if ($minBytes !== null && (int) $media->size < $minBytes) {
700	                    return false;
701	                }
702	
703	                if ($maxBytes !== null && (int) $media->size > $maxBytes) {
704	                    return false;
705	                }
706	
707	                if ($uploadedBy !== null) {
708	                    $mediaUploader = $media->getAttribute('uploaded_by_id');
709	                    if (! is_numeric($mediaUploader) || (int) $mediaUploader !== $uploadedBy) {
710	                        return false;
711	                    }
712	                }
713	
714	                // data di caricamento = created_at, confrontata come data locale
715	                // (Europe/Rome) per allinearsi a quanto mostrato nell'interfaccia
716	                if ($from !== null || $to !== null) {
717	                    $created = $media->created_at?->copy()->setTimezone('Europe/Rome')->toDateString();
718	                    if ($created === null) {
719	                        return false;
720	                    }
721	                    if ($from !== null && $created < $from) {
722	                        return false;
723	                    }
724	                    if ($to !== null && $created > $to) {
725	                        return false;
726	                    }
727	                }
728	
729	                return true;
730	            })
731	            ->values();
732	    }
