1059	    /**
1060	     * Carica uno o più file nella folder attiva (root se nessuna selezionata).
1061	     * I file finiscono nella collection asset del record (disco scoped).
1062	     */
1063	    public function uploadAssetsAction(): Action
1064	    {
1065	        return Action::make('uploadAssets')
1066	            ->label(__('digital-hub::assets.upload'))
1067	            ->icon(Heroicon::OutlinedArrowUpTray)
1068	            ->modalHeading(__('digital-hub::assets.upload_heading'))
1069	            ->schema([
1070	                FileUpload::make('files')
1071	                    ->label(__('digital-hub::assets.files_field'))
1072	                    ->multiple()
1073	                    ->required()
1074	                    ->storeFiles(false),
1075	            ])
1076	            ->action(function (array $data): void {
1077	                $owner = $this->resolveOwner();
1078	                $files = $data['files'] ?? [];
1079	                if (! is_array($files)) {
1080	                    return;
1081	                }
1082	
1083	                $count = 0;
1084	                foreach ($files as $file) {
1085	                    if (! $file instanceof TemporaryUploadedFile) {
1086	                        continue;
1087	                    }
1088	
1089	                    $media = $owner->addMedia($file)
1090	                        ->usingName(pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME))
1091	                        ->toMediaCollection($owner->assetsCollection());
1092	                    $media->setAttribute('asset_folder_id', $this->activeFolderId);
1093	
1094	                    // autore: FK nullable verso l'utente + snapshot del nome (fallback
1095	                    // se l'utente verrà eliminato → uploaded_by_id null per nullOnDelete)
1096	                    /** @disregard P1013 */
1097	                    $user = auth()->user();
1098	                    $media->setAttribute('uploaded_by_id', $user?->getAuthIdentifier());
1099	                    $media->setAttribute('uploaded_by_name', $user instanceof Model ? $user->getAttribute('name') : null);
1100	
1101	                    // l'elaborazione (metadati, dimensioni, future taglie) la fa un
1102	                    // job in coda: il media entra "pending" finché il job non lo chiude
1103	                    $media->setAttribute('processing_status', AssetProcessingStatus::Pending->value);
1104	                    $media->save();
1105	
1106	                    $this->dispatchProcessing($media);
1107	                    $count++;
1108	                }
1109	
1110	                if ($count > 0) {
1111	                    Notification::make()
1112	                        ->success()
1113	                        ->title(trans_choice('digital-hub::assets.assets_uploaded', $count, ['count' => $count]))
1114	                        ->send();
1115	                }
1116	            });
1117	    }
