// -- Helper per la view (griglia, selezione, polling) -------------------

/**
 * Sottocartelle da mostrare come tile: quelle dirette della folder attiva,
 * ma nessuna in vista filtrata (14c), dove la griglia è piatta e ignora le
 * cartelle.
 *
 * @return \Illuminate\Support\Collection<int, AssetFolder>
 */
public function subfoldersForView(): \Illuminate\Support\Collection
{
    return $this->hasActiveFilters() ? collect() : $this->getSubfolders();
}

/**
 * Miniature delle tile cartella (14b), saltate in vista filtrata (niente tile).
 *
 * @return array<int, list<array{url: string, inProgress: bool}>>
 */
public function subfolderPreviewsForView(): array
{
    return $this->hasActiveFilters() ? [] : $this->getSubfolderPreviews();
}

/**
 * Conteggi file delle tile cartella, saltati in vista filtrata.
 *
 * @return array<int, int>
 */
public function subfolderFileCountsForView(): array
{
    return $this->hasActiveFilters() ? [] : $this->getSubfolderFileCounts();
}

/**
 * C'è almeno un asset in lavorazione nella vista corrente (folder attiva o,
 * fuori dai filtri, nei sottoalberi delle sottocartelle)? Attiva il polling
 * della griglia solo finché serve.
 */
public function isProcessingVisible(): bool
{
    $inFolder = $this->getAssets()->contains(fn (Media $media): bool => $this->assetStatus($media)?->isInProgress() ?? false);

    return $inFolder || (! $this->hasActiveFilters() && $this->hasProcessingInSubfolders());
}

/**
 * Numero di elementi selezionati (file + cartelle) per la barra azioni multiple.
 */
public function selectedCount(): int
{
    return count($this->selectedAssetIds) + count($this->selectedFolderIds);
}

/**
 * C'è almeno una cartella nella selezione mista: sposta/elimina multipli
 * restano solo-file, quindi si nascondono in questo caso.
 */
public function hasFolderSelection(): bool
{
    return $this->selectedFolderIds !== [];
}

/** Un media è nella selezione corrente (confronto per chiave come stringa). */
public function isAssetSelected(Media $media): bool
{
    return in_array((string) $media->getKey(), array_map('strval', $this->selectedAssetIds), true);
}

/** Una cartella è nella selezione corrente (confronto per chiave come stringa). */
public function isFolderSelected(AssetFolder $folder): bool
{
    return in_array((string) $folder->getKey(), array_map('strval', $this->selectedFolderIds), true);
}

/**
 * Colore di sfondo delle card contenuto = "colore sfondo contenuto" delle
 * impostazioni generali (null se non impostato → sfondo di default).
 */
public function contentBackgroundColor(): ?string
{
    return app(\AtrioTeam\DigitalHub\Settings\GeneralSettings::class)->content_background_color;
}

// -- CRUD folder (#16a step 3) ------------------------------------------

