    $type = \AtrioTeam\DigitalHub\Assets\Support\AssetFileType::fromMedia($media);
    $isImage = $type->isImage();
    $poster = \AtrioTeam\DigitalHub\Assets\Support\AssetPreview::url($media);
    // miniatura per la griglia: thumbnail ottimizzato se c'è, altrimenti
    // l'originale per le immagini (già piccole), null per gli altri → icona
    $thumbUrl = $poster ?? ($isImage ? \AtrioTeam\DigitalHub\Assets\Support\AssetUrl::original($media) : null);
    $isSelected = $this->isAssetSelected($media);
    $status = $this->assetStatus($media);
    // risoluzione "W × H px" per immagini/video (null altrimenti)
