        // sfondo default quando "colore sfondo contenuto" non è impostato
        'bg-gray-50' => blank($contentBackground),
        // in dark mode lo sfondo è sempre quello delle card cartella: !important
        // per vincere sull'eventuale style inline del colore custom (solo light mode)
        'dark:bg-gray-800/50!',
        'border-gray-200 dark:border-gray-700' => ! $isSelected,
        'border-primary-500 ring-2 ring-primary-500' => $isSelected,
    ])
    @if (filled($contentBackground)) style="background-color: {{ $contentBackground }}" @endif
>
    {{-- Checkbox selezione, in alto a sx: a comparsa all'hover, sempre visibile se selezionato --}}
